const CLI_PATH = fileURLToPath(new URL("./cli.ts", import.meta.url));

function runCli(stdin: string): {
  stdout: string;
  stderr: string;
  status: number | null;
} {
  const result = spawnSync("npx", ["tsx", CLI_PATH], {
    input: stdin,
    encoding: "utf-8",
  });

  return {
    stdout: result.stdout,
    stderr: result.stderr,
    status: result.status,
  };
}

describe("claim-office CLI", () => {
  it("should write a results object to stdout for a scenario read from stdin", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 5 },
      steps: [
        {
          op: "quote",
          items: [
            {
              type: "amulet",
              material: "silver",
              enchantment: 2,
              cursed: false,
            },
          ],
        },
        {
          op: "claim",
          policy: 0,
          incident: {
            cause: "fire",
            damages: [{ itemType: "amulet", amount: 200 }],
          },
        },
      ],
    };

    const { stdout } = runCli(JSON.stringify(scenario));

    expect(JSON.parse(stdout)).toEqual({
      results: [{ premium: 143 }, { payout: 160, remainingCap: 640 }],
    });
  });

